mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode,
c1.C_Name_History as svcrProposeNameHistory, c1.C_Name as svcrProposeName, c1.C_Abbreviation as svcrProposeAbbName, mn.* from Con_Svcr mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on mn.Svcr_Propose_Id=c1.C_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Svcr_Create_Time desc
